// ═══════════════════════════════════════
// THREE.JS 3D PLANET + STARS BACKGROUND
// ═══════════════════════════════════════
function PlanetScene() {
  const mountRef = useRef(null);
  const frameRef = useRef(null);

  useEffect(() => {
    if (!mountRef.current) return;
    const container = mountRef.current;
    const W = () => container.clientWidth;
    const H = () => container.clientHeight;

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(W(), H());
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setClearColor(0x000000, 0);
    container.appendChild(renderer.domElement);

    // Scene & Camera
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(45, W() / H(), 0.1, 1000);
    camera.position.set(0, 0, 6);

    // ── Stars ──
    const starCount = 2000;
    const starGeo = new THREE.BufferGeometry();
    const starPos = new Float32Array(starCount * 3);
    const starSizes = new Float32Array(starCount);
    for (let i = 0; i < starCount; i++) {
      starPos[i * 3] = (Math.random() - 0.5) * 80;
      starPos[i * 3 + 1] = (Math.random() - 0.5) * 80;
      starPos[i * 3 + 2] = (Math.random() - 0.5) * 80;
      starSizes[i] = Math.random() * 2 + 0.5;
    }
    starGeo.setAttribute("position", new THREE.BufferAttribute(starPos, 3));
    starGeo.setAttribute("size", new THREE.BufferAttribute(starSizes, 1));
    const starMat = new THREE.PointsMaterial({
      color: 0xffffff,
      size: 0.08,
      transparent: true,
      opacity: 0.8,
      sizeAttenuation: true,
    });
    const stars = new THREE.Points(starGeo, starMat);
    scene.add(stars);

    // ── Planet ──
    const planetGeo = new THREE.SphereGeometry(1.8, 64, 64);

    // Procedural planet texture via canvas
    const texCanvas = document.createElement("canvas");
    texCanvas.width = 1024;
    texCanvas.height = 512;
    const ctx = texCanvas.getContext("2d");

    // Base gradient
    const baseGrad = ctx.createLinearGradient(0, 0, 1024, 512);
    baseGrad.addColorStop(0, "#1a0a3e");
    baseGrad.addColorStop(0.3, "#0d1b4a");
    baseGrad.addColorStop(0.5, "#162447");
    baseGrad.addColorStop(0.7, "#1f4068");
    baseGrad.addColorStop(1, "#0a1628");
    ctx.fillStyle = baseGrad;
    ctx.fillRect(0, 0, 1024, 512);

    // Continent-like shapes
    const continents = [
      { x: 200, y: 180, r: 120, color: "#2a1a5e" },
      { x: 500, y: 250, r: 150, color: "#1a3a6e" },
      { x: 750, y: 150, r: 100, color: "#2a2a5e" },
      { x: 350, y: 350, r: 90, color: "#1a2a5e" },
      { x: 850, y: 320, r: 130, color: "#1f2f5f" },
      { x: 100, y: 380, r: 80, color: "#2a1a4e" },
    ];
    continents.forEach((c) => {
      ctx.beginPath();
      ctx.ellipse(c.x, c.y, c.r * 1.3, c.r, Math.random() * Math.PI, 0, Math.PI * 2);
      ctx.fillStyle = c.color;
      ctx.fill();
    });

    // Noise dots
    for (let i = 0; i < 8000; i++) {
      const x = Math.random() * 1024;
      const y = Math.random() * 512;
      const brightness = Math.random() * 40 + 10;
      ctx.fillStyle = `rgba(${brightness + 30}, ${brightness + 50}, ${brightness + 100}, ${Math.random() * 0.3})`;
      ctx.fillRect(x, y, Math.random() * 3 + 1, Math.random() * 3 + 1);
    }

    // City lights
    for (let i = 0; i < 200; i++) {
      const x = Math.random() * 1024;
      const y = Math.random() * 512;
      ctx.beginPath();
      ctx.arc(x, y, Math.random() * 1.5 + 0.3, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(${180 + Math.random() * 75}, ${150 + Math.random() * 105}, ${255}, ${Math.random() * 0.6 + 0.2})`;
      ctx.fill();
    }

    // Glow veins (network lines)
    ctx.strokeStyle = "rgba(124, 92, 252, 0.08)";
    ctx.lineWidth = 0.8;
    for (let i = 0; i < 40; i++) {
      ctx.beginPath();
      ctx.moveTo(Math.random() * 1024, Math.random() * 512);
      ctx.quadraticCurveTo(
        Math.random() * 1024, Math.random() * 512,
        Math.random() * 1024, Math.random() * 512
      );
      ctx.stroke();
    }

    const planetTex = new THREE.CanvasTexture(texCanvas);
    planetTex.wrapS = THREE.RepeatWrapping;

    // Bump map canvas
    const bumpCanvas = document.createElement("canvas");
    bumpCanvas.width = 512;
    bumpCanvas.height = 256;
    const bCtx = bumpCanvas.getContext("2d");
    bCtx.fillStyle = "#808080";
    bCtx.fillRect(0, 0, 512, 256);
    for (let i = 0; i < 3000; i++) {
      const v = Math.random() * 100 + 100;
      bCtx.fillStyle = `rgb(${v},${v},${v})`;
      bCtx.fillRect(Math.random() * 512, Math.random() * 256, Math.random() * 6 + 1, Math.random() * 6 + 1);
    }
    const bumpTex = new THREE.CanvasTexture(bumpCanvas);

    const planetMat = new THREE.MeshPhongMaterial({
      map: planetTex,
      bumpMap: bumpTex,
      bumpScale: 0.06,
      specular: new THREE.Color(0x333366),
      shininess: 15,
    });
    const planet = new THREE.Mesh(planetGeo, planetMat);
    planet.position.set(2.2, -0.5, 0);
    scene.add(planet);

    // ── Atmosphere glow ──
    const atmosGeo = new THREE.SphereGeometry(1.95, 64, 64);
    const atmosMat = new THREE.MeshBasicMaterial({
      color: 0x4444ff,
      transparent: true,
      opacity: 0.07,
      side: THREE.BackSide,
    });
    const atmosphere = new THREE.Mesh(atmosGeo, atmosMat);
    atmosphere.position.copy(planet.position);
    scene.add(atmosphere);

    // ── Ring (orbit ring) ──
    const ringGeo = new THREE.TorusGeometry(2.8, 0.015, 16, 100);
    const ringMat = new THREE.MeshBasicMaterial({
      color: 0x7c5cfc,
      transparent: true,
      opacity: 0.25,
    });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.position.copy(planet.position);
    ring.rotation.x = Math.PI * 0.42;
    scene.add(ring);

    // ── Orbiting particles ──
    const orbitParticleCount = 60;
    const orbitGeo = new THREE.BufferGeometry();
    const orbitPos = new Float32Array(orbitParticleCount * 3);
    const orbitAngles = [];
    for (let i = 0; i < orbitParticleCount; i++) {
      orbitAngles.push(Math.random() * Math.PI * 2);
      const a = orbitAngles[i];
      const r = 2.8 + (Math.random() - 0.5) * 0.3;
      orbitPos[i * 3] = Math.cos(a) * r + planet.position.x;
      orbitPos[i * 3 + 1] = (Math.random() - 0.5) * 0.3 + planet.position.y;
      orbitPos[i * 3 + 2] = Math.sin(a) * r;
    }
    orbitGeo.setAttribute("position", new THREE.BufferAttribute(orbitPos, 3));
    const orbitMat = new THREE.PointsMaterial({
      color: 0x00d4ff,
      size: 0.04,
      transparent: true,
      opacity: 0.7,
      sizeAttenuation: true,
    });
    const orbitParticles = new THREE.Points(orbitGeo, orbitMat);
    scene.add(orbitParticles);

    // ── Lights ──
    const sunLight = new THREE.DirectionalLight(0xffffff, 1.2);
    sunLight.position.set(-5, 3, 5);
    scene.add(sunLight);

    const rimLight = new THREE.DirectionalLight(0x7c5cfc, 0.5);
    rimLight.position.set(5, -2, -3);
    scene.add(rimLight);

    const ambientLight = new THREE.AmbientLight(0x222244, 0.6);
    scene.add(ambientLight);

    // ── Mouse parallax ──
    let mouseX = 0, mouseY = 0;
    const onMouse = (e) => {
      mouseX = (e.clientX / W() - 0.5) * 2;
      mouseY = (e.clientY / H() - 0.5) * 2;
    };
    window.addEventListener("mousemove", onMouse);

    // ── Scroll factor ──
    let scrollFactor = 0;
    const onScroll = () => {
      scrollFactor = window.scrollY / (document.body.scrollHeight - window.innerHeight || 1);
    };
    window.addEventListener("scroll", onScroll, { passive: true });

    // ── Animate ──
    let time = 0;
    const animate = () => {
      frameRef.current = requestAnimationFrame(animate);
      time += 0.003;

      // Planet rotation
      planet.rotation.y += 0.0015;
      atmosphere.rotation.y += 0.001;
      ring.rotation.z += 0.001;

      // Stars slow drift
      stars.rotation.y += 0.0001;
      stars.rotation.x += 0.00005;

      // Orbit particles
      const oPos = orbitGeo.attributes.position.array;
      for (let i = 0; i < orbitParticleCount; i++) {
        orbitAngles[i] += 0.003 + i * 0.00002;
        const r = 2.8 + Math.sin(time * 2 + i) * 0.15;
        oPos[i * 3] = Math.cos(orbitAngles[i]) * r + planet.position.x;
        oPos[i * 3 + 1] = Math.sin(orbitAngles[i] * 0.5) * 0.3 + planet.position.y;
        oPos[i * 3 + 2] = Math.sin(orbitAngles[i]) * r;
      }
      orbitGeo.attributes.position.needsUpdate = true;

      // Camera parallax
      camera.position.x += (mouseX * 0.3 - camera.position.x) * 0.03;
      camera.position.y += (-mouseY * 0.2 - camera.position.y) * 0.03;
      camera.lookAt(0.5, 0, 0);

      // Scroll: planet drifts
      planet.position.y = -0.5 - scrollFactor * 3;
      atmosphere.position.y = planet.position.y;
      ring.position.y = planet.position.y;

      renderer.render(scene, camera);
    };
    animate();

    // Resize
    const onResize = () => {
      camera.aspect = W() / H();
      camera.updateProjectionMatrix();
      renderer.setSize(W(), H());
    };
    window.addEventListener("resize", onResize);

    return () => {
      cancelAnimationFrame(frameRef.current);
      window.removeEventListener("mousemove", onMouse);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onResize);
      container.removeChild(renderer.domElement);
      renderer.dispose();
    };
  }, []);

  return (
    <div
      ref={mountRef}
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 0,
        pointerEvents: "none",
      }}
    />
  );
}

