function Reveal({ children, delay = 0, className = "" }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) setVisible(true); },
      { threshold: 0.12 }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return (
    <div
      ref={ref}
      className={className}
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0) scale(1)" : "translateY(50px) scale(0.97)",
        transition: `all 0.9s cubic-bezier(0.22, 1, 0.36, 1) ${delay}s`,
      }}
    >
      {children}
    </div>
  );
}

function Counter({ end, suffix = "", duration = 2000 }) {
  const [count, setCount] = useState(0);
  const ref = useRef(null);
  const started = useRef(false);
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting && !started.current) {
          started.current = true;
          let s = 0;
          const step = end / (duration / 16);
          const t = setInterval(() => {
            s += step;
            if (s >= end) { setCount(end); clearInterval(t); }
            else setCount(Math.floor(s));
          }, 16);
        }
      },
      { threshold: 0.5 }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [end, duration]);
  return <span ref={ref}>{count}{suffix}</span>;
}

function TypingText({ texts, speed = 80, pause = 2000 }) {
  const [displayed, setDisplayed] = useState("");
  const [ti, setTi] = useState(0);
  const [ci, setCi] = useState(0);
  const [del, setDel] = useState(false);
  useEffect(() => {
    const cur = texts[ti];
    let timeout;
    if (!del && ci < cur.length) {
      timeout = setTimeout(() => { setDisplayed(cur.slice(0, ci + 1)); setCi(ci + 1); }, speed);
    } else if (!del && ci === cur.length) {
      timeout = setTimeout(() => setDel(true), pause);
    } else if (del && ci > 0) {
      timeout = setTimeout(() => { setDisplayed(cur.slice(0, ci - 1)); setCi(ci - 1); }, speed / 2);
    } else if (del && ci === 0) {
      setDel(false);
      setTi((ti + 1) % texts.length);
    }
    return () => clearTimeout(timeout);
  }, [ci, del, ti, texts, speed, pause]);
  return (
    <span>
      {displayed}
      <span style={{ borderRight: `2px solid ${C.cyan}`, animation: "blink 1s step-end infinite", marginLeft: 2 }} />
    </span>
  );
}

